import{_ as e,o as a,c as n,a5 as r}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"06 — AI Features","description":"","frontmatter":{},"headers":[],"relativePath":"ba/06-ai-features.md","filePath":"ba/06-ai-features.md"}'),o={name:"ba/06-ai-features.md"};function i(d,t,h,l,c,s){return a(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="_06-—-ai-features" tabindex="-1">06 — AI Features <a class="header-anchor" href="#_06-—-ai-features" aria-label="Permalink to &quot;06 — AI Features&quot;">​</a></h1><p>&gt; <a href="./00-overview.html">&lt;&lt; Về Overview</a></p><h2 id="danh-sach-fr-đay-đu-3-7-1-–-3-7-12" tabindex="-1">Danh sách FR đầy đủ (3.7.1 – 3.7.12) <a class="header-anchor" href="#danh-sach-fr-đay-đu-3-7-1-–-3-7-12" aria-label="Permalink to &quot;Danh sách FR đầy đủ (3.7.1 – 3.7.12)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>FR</th><th>Tên</th><th>Role</th><th>Mô tả</th></tr></thead><tbody><tr><td>3.7.1</td><td>View Trending Topics Suggestions</td><td>CREATOR</td><td>Dashboard xem keyword trend hiện tại</td></tr><tr><td>3.7.2</td><td>Generate Caption</td><td>CREATOR</td><td>Dùng LLM + prompt để tạo caption cho bài post</td></tr><tr><td>3.7.3</td><td>Generate Ambassador</td><td>CREATOR</td><td>Dùng LLM generate Model (người ảo) khi brand không có model thật. Model được dùng để generate Image và Video</td></tr><tr><td>3.7.4</td><td>View Image Style Template</td><td>CREATOR</td><td>Gợi ý template mẫu phong cách (anime, mùa xuân, hồi ức...) để tạo Image theo style mà không cần mô tả nhiều</td></tr><tr><td>3.7.5</td><td>Generate Image</td><td>CREATOR</td><td>Dùng LLM + prompt tạo Image. Input = form + model + materials khác → chuyển thành prompt. Có LoRA lai với model LLM gen Image</td></tr><tr><td>3.7.6</td><td>View Video Style Template</td><td>CREATOR</td><td>Tương tự 3.7.4 nhưng áp dụng cho LLM gen Video</td></tr><tr><td>3.7.7</td><td>Generate Video</td><td>CREATOR</td><td>Dùng LLM + prompt tạo Video (dùng API gen video bên thứ 3). Có thể mở rộng thành studio</td></tr><tr><td>3.7.8</td><td>Export File</td><td>CREATOR</td><td>Export file về máy sau khi generate, nhiều định dạng — chủ yếu upload social thì mp4 hoặc webM</td></tr><tr><td>3.7.9</td><td>Crawl Schedule Config</td><td>ADMIN</td><td>Cấu hình bộ cào data phục vụ tìm keyword trend: thời gian, page nào, số bài/lần</td></tr><tr><td>3.7.10</td><td>Suggest Hashtag Trend</td><td>CREATOR</td><td>Gợi ý hashtag trend cho content creator</td></tr><tr><td>3.7.11</td><td>Generate Livestream Script</td><td>CREATOR</td><td>Tạo mẫu kịch bản cho livestream</td></tr><tr><td>3.7.12</td><td>Recommend Collaborator</td><td>CREATOR</td><td>Gợi ý bên thứ 3 (báo điện tử, trang chạy banner, kênh TV) để Client chọn làm đối tác truyền thông cho chiến dịch, có phân cấp option</td></tr></tbody></table><h2 id="ghi-chu-nghiep-vu-quan-trong" tabindex="-1">Ghi chú nghiệp vụ quan trọng <a class="header-anchor" href="#ghi-chu-nghiep-vu-quan-trong" aria-label="Permalink to &quot;Ghi chú nghiệp vụ quan trọng&quot;">​</a></h2><h3 id="generate-ambassador-→-image-video-3-7-3" tabindex="-1">Generate Ambassador → Image/Video (3.7.3) <a class="header-anchor" href="#generate-ambassador-→-image-video-3-7-3" aria-label="Permalink to &quot;Generate Ambassador → Image/Video (3.7.3)&quot;">​</a></h3><ul><li>Model ảo (Ambassador) sinh ra từ LLM được <strong>dùng làm input</strong> cho cả Generate Image và Generate Video — không phải feature độc lập, mà là 1 nguồn &quot;diễn viên ảo&quot; tái sử dụng xuyên suốt pipeline tạo nội dung khi brand không có người mẫu/đại sứ thật.</li></ul><h3 id="generate-image-—-pipeline-input-3-7-5" tabindex="-1">Generate Image — pipeline input (3.7.5) <a class="header-anchor" href="#generate-image-—-pipeline-input-3-7-5" aria-label="Permalink to &quot;Generate Image — pipeline input (3.7.5)&quot;">​</a></h3><ul><li>Input để generate ảnh = <strong>form (do Creator điền) + model (ambassador nếu có) + materials khác</strong> (từ Material Repository/Brand Collection) → hệ thống ghép lại thành 1 prompt hoàn chỉnh gửi cho model AI.</li><li>Có sử dụng <strong>LoRA</strong> lai (fine-tune nhẹ) với model LLM gen Image — cho phép custom phong cách riêng theo brand.</li></ul><h3 id="recommend-collaborator-3-7-12-—-lien-ket-module-moi" tabindex="-1">Recommend Collaborator (3.7.12) — liên kết module mới <a class="header-anchor" href="#recommend-collaborator-3-7-12-—-lien-ket-module-moi" aria-label="Permalink to &quot;Recommend Collaborator (3.7.12) — liên kết module mới&quot;">​</a></h3><ul><li>Đây chính là AI tool hỗ trợ cho module <strong>Third-party Collaborator</strong> (đối tác truyền thông ngoài social media) — xem chi tiết đầy đủ ở <a href="./07-publishing-social-collaborator.html">07-publishing-social-collaborator.md</a> mục 2.</li><li>AI chỉ <strong>gợi ý</strong> — không tự động ký kết hay liên hệ, quyết định cuối vẫn do Client/Manager chọn.</li></ul><h3 id="crawl-schedule-config-3-7-9-—-duy-nhat-thuoc-admin" tabindex="-1">Crawl Schedule Config (3.7.9) — duy nhất thuộc ADMIN <a class="header-anchor" href="#crawl-schedule-config-3-7-9-—-duy-nhat-thuoc-admin" aria-label="Permalink to &quot;Crawl Schedule Config (3.7.9) — duy nhất thuộc ADMIN&quot;">​</a></h3><ul><li>Đây là FR AI duy nhất trong nhóm 3.7 thuộc quyền ADMIN (không phải CREATOR) — vì việc cấu hình crawler ảnh hưởng toàn hệ thống (tài nguyên server, tần suất gọi API bên ngoài), không phải thao tác cấp workspace.</li></ul><h3 id="generate-livestream-script-3-7-11-—-ho-tro-loai-task-livestream" tabindex="-1">Generate Livestream Script (3.7.11) — hỗ trợ Loại Task Livestream <a class="header-anchor" href="#generate-livestream-script-3-7-11-—-ho-tro-loai-task-livestream" aria-label="Permalink to &quot;Generate Livestream Script (3.7.11) — hỗ trợ Loại Task Livestream&quot;">​</a></h3><ul><li>Tool này hỗ trợ trực tiếp cho FR 3.6.23 (Write Livestream Script) ở <a href="./05-content-task-workflow.html">05-content-task-workflow.md</a> — Creator dùng AI để có bản kịch bản mẫu trước khi tự viết/chỉnh sửa hoàn chỉnh.</li></ul>',15)])])}const u=e(o,[["render",i]]);export{g as __pageData,u as default};
